use keyforge_physics::EngineFactory;
use keyforge_infra::AssetManager;
use keyforge_model::geometry::KeyboardDefinition;
use keyforge_model::{Corpus, CostModel, KeyCode, Keyboard, Layout, Rubric};
use serde::{Deserialize, Serialize};
use std::path::Path;
use std::time::{Duration, Instant};
use tracing::{info, warn};

use crate::agent::errors::AgentError;

#[derive(Serialize, Deserialize)]
struct CalibrationData {
    ips: f64,
    timestamp: u64,
    version: String,
}

fn default_cost_model() -> CostModel {
    // Minimal valid cost model for calibration
    let json = r#"{
        "meta": { "version": "2.0", "description": "Calibration", "unit": "pts" },
        "models": {
            "model_a_row_staggered": {
                "description": "Calibration Model",
                "static_costs": {
                    "universal_hand": {
                        "thumb": { "pos_1": 100.0 },
                        "index": { "base": { "r0": 100.0 } },
                        "middle": { "base": { "r0": 100.0 } },
                        "ring": { "base": { "r0": 100.0 } },
                        "pinky": { "base": { "r0": 100.0 } }
                    }
                }
            }
        },
        "dynamic_rules": { "sequence_modifiers": {}, "penalties": {}, "constraints": {} }
    }"#;
    #[allow(clippy::unwrap_used)]
    serde_json::from_str(json).unwrap()
}

/// # Errors
///
/// Returns an error if asset loading, keyboard parsing, or benchmarking fails.
///
/// # Panics
///
/// Panics if JSON serialization of calibration data fails (should never happen with valid data).
pub async fn calibrate(
    assets: &AssetManager,
    data_root: &Path,
    config: &crate::models::CalibrationConfig,
) -> Result<f64, AgentError> {
    let cal_path = data_root.join("user/calibration.json");

    if cal_path.exists() {
        if let Ok(content) = tokio::fs::read_to_string(&cal_path).await {
            if let Ok(data) = serde_json::from_str::<CalibrationData>(&content) {
                info!("Loaded cached calibration: {:.2} kOPS", data.ips / 1000.0);
                return Ok(data.ips);
            }
        }
        warn!("Invalid calibration file, recalibrating...");
    }

    info!("Starting hardware calibration...");

    let kb_path = assets
        .ensure_keyboard("corne")
        .await
        .map_err(|e| AgentError::Calibration(format!("Failed to fetch reference keyboard: {e}")))?;

    let content = tokio::fs::read_to_string(&kb_path)
        .await
        .map_err(|e| AgentError::Calibration(format!("Failed to read keyboard: {e}")))?;

    let def: KeyboardDefinition = serde_json::from_str(&content)
        .map_err(|e| AgentError::Calibration(format!("Invalid keyboard JSON: {e}")))?;

    let keyboard = Keyboard::new(def.geometry.keys, def.geometry.home_row)
        .map_err(|e| AgentError::Calibration(e.to_string()))?;

    let ips = if config.duration_ms == 0 {
        info!("Skipping hardware calibration (duration_ms=0)");
        1_000_000.0
    } else {
        run_benchmark(&keyboard, config)?
    };

    let data = CalibrationData {
        ips,
        timestamp: std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap_or_default()
            .as_secs(),
        version: env!("CARGO_PKG_VERSION").to_string(),
    };

    if let Some(parent) = cal_path.parent() {
        tokio::fs::create_dir_all(parent)
            .await
            .map_err(|e| AgentError::Resource(e.to_string()))?;
    }

    #[allow(clippy::unwrap_used)]
    let json = serde_json::to_string(&data).unwrap();
    tokio::fs::write(&cal_path, json)
        .await
        .map_err(|e| AgentError::Resource(e.to_string()))?;

    info!("Calibration complete: {:.2} kOPS", ips / 1000.0);
    Ok(ips)
}

#[allow(clippy::cast_possible_truncation, clippy::cast_precision_loss)]
#[allow(clippy::needless_borrow)]
fn run_benchmark(
    keyboard: &Keyboard,
    config: &crate::models::CalibrationConfig,
) -> Result<f64, AgentError> {
    let key_count = keyboard.keys.len();
    let corpus = Corpus::default();
    let rubric = Rubric::default();
    let cost_model = default_cost_model();

    let layout = Layout::new_unchecked((0..key_count as u16).map(KeyCode).collect());

    let engine = EngineFactory::new_generic(&keyboard, &corpus, &rubric, &cost_model)
        .map_err(|e| AgentError::Calibration(e.to_string()))?;

    for _ in 0..config.warmup_iterations {
        let _ = engine.score(&layout);
    }

    let start = Instant::now();
    let duration = Duration::from_millis(config.duration_ms);
    let mut iterations: u64 = 0;
    let batch = config.batch_size;

    while start.elapsed() < duration {
        for _ in 0..batch {
            let _ = engine.score(&layout);
        }
        iterations += batch as u64;
    }

    let elapsed = start.elapsed().as_secs_f64();
    if elapsed == 0.0 {
        return Ok(0.0);
    }

    Ok(iterations as f64 / elapsed)
}

#[allow(clippy::cast_possible_truncation, clippy::cast_precision_loss)]
pub fn measure_performance(config: &crate::models::CalibrationConfig) -> Result<f64, AgentError> {
    let mut keys = Vec::with_capacity(config.key_count);
    for i in 0..config.key_count {
        keys.push(keyforge_model::geometry::KeyNode {
            index: i,
            #[allow(clippy::cast_precision_loss)]
            x: i as f32,
            y: 0.0,
            ..Default::default()
        });
    }
    let keyboard = Keyboard::new(keys, 0).map_err(|e| AgentError::Calibration(e.to_string()))?;
    run_benchmark(&keyboard, config)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::models::CalibrationConfig;

    #[test]
    fn test_performance_calibration() {
        let config = CalibrationConfig {
            key_count: 10,
            warmup_iterations: 1,
            duration_ms: 100,
            batch_size: 10,
        };
        let ops = measure_performance(&config).unwrap();
        assert!(ops > 0.0, "Calibration should report positive throughput");
    }
}

