use crate::models::SharedTelemetry;
use keyforge_core::ProgressCallback;
use keyforge_model::KeyCode;
use std::collections::hash_map::DefaultHasher;
use std::hash::{Hash, Hasher};
use std::sync::atomic::{AtomicBool, Ordering};
use std::sync::Arc;
use tracing::info;

/// A logger that tracks optimization progress and reports it back to the system.
#[derive(Debug)]
pub struct WorkerLogger {
    /// Atomic flag used to signals the engine to stop gracefully.
    pub stop_flag: Arc<AtomicBool>,
    /// The unique identifier of the job being logged.
    pub job_id: String,
    /// Shared telemetry handle for live metric updates.
    pub telemetry: SharedTelemetry,
    /// Rate at which to log progress (e.g. every N steps).
    pub sample_rate: usize,
}

impl ProgressCallback for WorkerLogger {
    fn on_progress(&self, step: usize, score: f32, _layout: &[KeyCode], ips: f32) -> bool {
        let stopped = self.stop_flag.load(Ordering::SeqCst);

        // Update shared telemetry (Lock-free)
        self.telemetry.update(ips, 0.0, score);

        if stopped {
            return false;
        }

        let mut hasher = DefaultHasher::new();
        self.job_id.hash(&mut hasher);
        step.hash(&mut hasher);
        let hash = hasher.finish();

        if hash.is_multiple_of((self.sample_rate as u64).max(1)) {
            info!(
                job_id = %self.job_id,
                step = step,
                score = score,
                ips = ips,
                "optimization progress"
            );
        }
        true
    }
}

use anyhow::Result;
use keyforge_infra::FsProvider;
use keyforge_model::{KeyCode, Layout};
use keyforge_runner::{OptimizationRunner, RunnerOptions};
use std::path::PathBuf;

use crate::config_loader::read_job_config;
use crate::models::AgentConfig;

/// Runs a micro-benchmark for scoring performance.
///
/// # Errors
///
/// Returns an error if the job configuration cannot be read or scoring fails.
pub async fn run(config: AgentConfig, job_file: PathBuf, iterations: usize) -> Result<()> {
    let job = read_job_config(&job_file).await?;

    let loader = FsProvider::new(config.data_dir.clone());
    let options = RunnerOptions {
        keycodes_file: config.compute.keycodes_file.clone(),
        ..Default::default()
    };

    let session = OptimizationRunner::prepare_session(&loader, &job, &options).await?;

    let start = std::time::Instant::now();
    let mut score_sum = 0.0;

    let engine = session.engine;
    let default_layout = Layout::new_unchecked(vec![KeyCode(0); engine.key_count()]);

    for _ in 0..iterations {
        score_sum += engine.score(&default_layout)?.to_f32();
    }

    let duration = start.elapsed();
    #[allow(clippy::cast_precision_loss)]
    let kops = (iterations as f64 / duration.as_secs_f64()) / 1000.0;

    println!(
        "{}",
        serde_json::json!({
            "iterations": iterations,
            "duration_ms": duration.as_millis(),
            "kops": kops,
            "checksum": score_sum
        })
    );
    Ok(())
}

