use anyhow::Result;
use std::path::PathBuf;
use tokio::sync::mpsc;
use tracing::error;

use crate::config_loader::read_job_config;
use crate::models::AgentConfig;

/// Executes a local optimization job.
///
/// # Errors
///
/// Returns an error if the job configuration cannot be read or optimization fails.
///
/// # Panics
///
/// Panics if result serialization fails.
pub async fn run(mut config: AgentConfig, job_file: PathBuf, timeout: Option<u64>) -> Result<()> {
    let job = read_job_config(&job_file).await?;

    if let Some(t) = timeout {
        config.compute.job_timeout_sec = t;
    }

    let (result_tx, mut result_rx) = mpsc::channel(1);

    let agent = crate::agent::Agent::new(config.clone(), result_tx)
        .await
        .map_err(|e| anyhow::anyhow!("Failed to init agent: {e}"))?;

    let (job_tx, job_rx) = mpsc::channel(1);
    let (_stop_tx, stop_rx) = mpsc::channel(1);

    let agent_handle = tokio::spawn(async move { agent.run(job_rx, stop_rx).await });

    let job_id = "local-job".to_string();
    job_tx.send((job_id, job)).await.ok();

    if let Some(result) = result_rx.recv().await {
        #[allow(clippy::unwrap_used)]
        let json = serde_json::to_string(&result).unwrap();
        println!("{json}");
    } else {
        error!("No result produced!");
        std::process::exit(1);
    }

    drop(job_tx);
    let _ = agent_handle.await;
    Ok(())
}

use anyhow::Result;
use keyforge_infra::FsProvider;
use keyforge_runner::{OptimizationRunner, RunnerOptions};
use std::path::PathBuf;
use tracing::info;

use crate::config_loader::read_job_config;
use crate::models::AgentConfig;

/// Scores a specific layout configuration.
///
/// # Errors
///
/// Returns an error if the job or layout is invalid, or if scoring fails.
pub async fn run(
    mut config: AgentConfig,
    job_file: PathBuf,
    layout: String,
    timeout: Option<u64>,
) -> Result<()> {
    info!("Scoring layout: '{}'", layout);

    let job = read_job_config(&job_file).await?;

    if let Some(t) = timeout {
        config.compute.job_timeout_sec = t;
    }

    let loader = FsProvider::new(config.data_dir.clone());
    let options = RunnerOptions {
        keycodes_file: config.compute.keycodes_file.clone(),
        ..Default::default()
    };

    let session = OptimizationRunner::prepare_session(&loader, &job, &options).await?;

    // Try to resolve as layout name from definition first, then parse as raw string
    let layout_parsed = if let Some(layout_str) = job.definition.layouts.get(&layout) {
        keyforge_adapter::conversion::parse_layout_string(
            layout_str,
            session.engine.key_count(),
            &session.registry,
        )
        .map_err(|e| anyhow::anyhow!("Invalid layout in definition: {e}"))?
    } else {
        keyforge_adapter::conversion::parse_layout_string(
            &layout,
            session.engine.key_count(),
            &session.registry,
        )
        .map_err(|e| anyhow::anyhow!("Invalid layout string: {e}"))?
    };

    let report = session.engine.analyze(&layout_parsed);
    match report {
        Ok(r) => println!("{}", serde_json::to_string_pretty(&r)?),
        Err(e) => return Err(anyhow::anyhow!("Analysis failed: {e:?}")),
    }
    Ok(())
}

use anyhow::Result;
use ed25519_dalek::VerifyingKey;
use sha2::{Digest, Sha256};
use tokio::sync::broadcast;
use tracing::info;

use crate::identity::load_or_create_identity;
use crate::models::AgentConfig;

/// Starts the agent in worker mode, connecting to the Hive.
///
/// # Errors
///
/// Returns an error if identity loading or signal registration fails.
pub async fn run(config: AgentConfig) -> Result<()> {
    let signing_key = load_or_create_identity(&config.system)?;
    let public_key = VerifyingKey::from(&signing_key);

    let mut hasher = Sha256::new();
    hasher.update(public_key.to_bytes());
    let pk_hash = hex::encode(hasher.finalize());
    let node_id = format!("{}{}", config.system.node_id_prefix, &pk_hash[0..8]);

    info!("agent starting in WORKER mode");
    info!(hive_url = %config.hive_url, "connecting to hive");
    info!(data_dir = ?config.data_dir, "data directory configured");

    let (tx, rx) = broadcast::channel(config.system.shutdown_channel_capacity);
    #[cfg(unix)]
    let mut sig_usr1 =
        tokio::signal::unix::signal(tokio::signal::unix::SignalKind::user_defined1())
            .map_err(|e| anyhow::anyhow!("failed to register SIGUSR1: {e}"))?;
    #[cfg(not(unix))]
    let mut sig_usr1 = std::future::pending::<()>();

    let tx_clone = tx.clone();
    tokio::spawn(async move {
        tokio::select! {
            _ = tokio::signal::ctrl_c() => {
                let _ = tx_clone.send(());
            }
            _ = sig_usr1.recv() => {
                let _ = tx_clone.send(());
            }
        }
    });

    crate::agent::run_worker(config, node_id, signing_key, rx).await;
    Ok(())
}

