    #[test]
    fn test_version_comparison() {
        assert!(version_greater_than("0.9.0", "0.8.0"));
        assert!(version_greater_than("1.0.0", "0.9.9"));
        assert!(!version_greater_than("0.8.0", "0.9.0"));
