/// Builds and returns the Axum router for system-related endpoints.
pub fn system_routes() -> Router<Arc<AppState>> {
    Router::new()
        .route("/", get(root))
        .route("/health", get(health))
        .route("/ws", get(crate::api::ws::handler))
