use sqlx::{Pool, Postgres};

/// Repository for managing compute nodes and hardware profiles.
#[derive(Clone, Debug)]
pub struct NodeRepository {
    pool: Pool<Postgres>,
}

impl NodeRepository {
    /// Creates a new `NodeRepository` with the given database pool.
    #[must_use]
    pub fn new(pool: Pool<Postgres>) -> Self {
        Self { pool }
    }

    /// Full Registration: UPSERTs Hardware Profile AND Node.
    /// Used when Valkey indicates the Hardware Profile is new/unknown.
    pub async fn register_heartbeat(
        &self,
        node_id: &str,
        cpu_model: &str,
        cores: i32,
        l2_cache_kb: Option<i32>,
        ops_per_sec: f32,
        public_key: Option<&str>,
    ) -> Result<(), sqlx::Error> {
        self.verify_key(node_id, public_key).await?;

        sqlx::query("SELECT register_node_heartbeat($1, $2, $3, $4, $5, $6, $7)")
            .bind(node_id)
            .bind(cpu_model)
            .bind(std::env::consts::ARCH)
            .bind(cores)
            .bind(l2_cache_kb)
            .bind(ops_per_sec)
            .bind(public_key)
            .execute(&self.pool)
            .await?;
        Ok(())
    }

    /// Lite Registration: UPSERTs Node ONLY.
    /// Optimized path that avoids locking the `hardware_profiles` table.
    pub async fn register_heartbeat_lite(
        &self,
        node_id: &str,
        cpu_model: &str,
        cores: i32,
        ops_per_sec: f32,
        public_key: Option<&str>,
    ) -> Result<(), sqlx::Error> {
        self.verify_key(node_id, public_key).await?;

        sqlx::query(
            r"
            INSERT INTO nodes (
                id, cpu_signature, cpu_cores, performance_rating, 
                last_seen, public_key
            )
            VALUES ($1, $2, $3, $4, CURRENT_TIMESTAMP, $5)
            ON CONFLICT (id) DO UPDATE
            SET last_seen = CURRENT_TIMESTAMP,
                performance_rating = EXCLUDED.performance_rating,
                cpu_cores = EXCLUDED.cpu_cores,
                public_key = COALESCE(nodes.public_key, EXCLUDED.public_key)
            ",
        )
        .bind(node_id)
        .bind(cpu_model)
        .bind(cores)
        .bind(ops_per_sec)
        .bind(public_key)
        .execute(&self.pool)
        .await?;
        Ok(())
    }

    /// Verifies that the public key matches the one stored for the node ID.
    async fn verify_key(&self, node_id: &str, public_key: Option<&str>) -> Result<(), sqlx::Error> {
        let existing_key = self.get_public_key(node_id).await?;

        match (existing_key, public_key) {
            (Some(existing), Some(new)) => {
                let existing_clean = existing.trim();
                let new_clean = new.trim();

                if !existing_clean.is_empty() && existing_clean != new_clean {
                    tracing::warn!("🚨 Security Alert: Node Identity Mismatch for {}", node_id);
                    return Err(sqlx::Error::Protocol(
                        "Node Identity Mismatch: Public Key changed".into(),
                    ));
                }
            }
            (Some(_), None) => {
                tracing::warn!(
                    "🚨 Security Alert: Node {} attempted heartbeat without public key",
                    node_id
                );
                return Err(sqlx::Error::Protocol(
                    "Identity Required: Public Key must be provided for registered nodes".into(),
                ));
            }
            _ => {} // New node or no key in DB, allow
        }
        Ok(())
    }

    /// Retrieves the registered public key for a node.
    pub async fn get_public_key(&self, node_id: &str) -> Result<Option<String>, sqlx::Error> {
        let row: Option<Option<String>> =
            sqlx::query_scalar("SELECT public_key FROM nodes WHERE id = $1")
                .bind(node_id)
                .fetch_optional(&self.pool)
                .await?;
        Ok(row.flatten())
    }

    /// Prunes nodes that haven't been seen within the specified interval.
    pub async fn prune_inactive_nodes(&self, minutes: i32) -> Result<u64, sqlx::Error> {
        let result =
            sqlx::query("DELETE FROM nodes WHERE last_seen < NOW() - make_interval(mins => $1)")
                .bind(minutes)
                .execute(&self.pool)
                .await?;
        Ok(result.rows_affected())
    }
}

