pub fn ensure_test_assets(data_root: &Path) {
    // Create User Structure
    let kb_dir = data_root.join("user/keyboards");
    fs::create_dir_all(&kb_dir).unwrap();
    let weights_dir = data_root.join("user/weights");
    fs::create_dir_all(&weights_dir).unwrap();
    let corpus_dir = data_root.join("user/corpora/default");
    fs::create_dir_all(&corpus_dir).unwrap();
    let config_dir = data_root.join("user/config");
    fs::create_dir_all(&config_dir).unwrap();

    let cost_path = weights_dir.join("cost_matrix.json");
    if !cost_path.exists() {
        fs::write(
            cost_path,
            r#"[{"from_key":"KA","to_key":"KB","cost_ms":10.0,"confidence_samples":10}]"#,
        )
        .unwrap();
    }

    if !corpus_dir.join("1grams.json").exists() {
        fs::write(
            corpus_dir.join("1grams.json"),
            r#"[{"char":"a","freq":100}]"#,
        )
        .unwrap();
        fs::write(
            corpus_dir.join("2grams.json"),
            r#"[{"char1":"a","char2":"b","freq":10}]"#,
        )
        .unwrap();
        fs::write(
            corpus_dir.join("3grams.json"),
            r#"[{"char1":"a","char2":"b","char3":"c","freq":5}]"#,
        )
        .unwrap();
        fs::write(
            corpus_dir.join("words.json"),
            r#"[{"word":"test","freq":20}]"#,
        )
        .unwrap();
    }

    // Create dummy keycodes
    if !config_dir.join("keycodes.json").exists() {
        fs::write(
            config_dir.join("keycodes.json"),
            r#"[{"code": 97, "id": "KC_A", "label": "A", "aliases": []}]"#,
        )
        .unwrap();
    }

    // Create dummy keyboards
    for name in ["corne", "szr35"] {
        let path = kb_dir.join(format!("{}.json", name));
        if !path.exists() {
            let json = format!(
                r#"{{
                "meta": {{ "name": "{}", "author": "test", "version": "1", "type": "ortho" }},
                "geometry": {{
                    "keys": [
                        {{"id": "KC_A", "x":0,"y":0,"hand":0,"finger":1,"row":0,"col":0}},
                        {{"id": "KC_B", "x":1,"y":0,"hand":0,"finger":2,"row":0,"col":1}}
                    ],
                    "prime_slots": [0, 1], "med_slots": [], "low_slots": [], "home_row": 0
                }},
                "layouts": {{ "default": "KC_A KC_B" }}
            }}"#,
                name
            );
            fs::write(path, json).unwrap();
        }
    }
}

pub fn load_keyboard(data_root: &Path, name: &str) -> KeyboardDefinition {
    let path = data_root.join(format!("user/keyboards/{}.json", name));
    let content = fs::read_to_string(&path).unwrap_or_else(|_| panic!("Failed to read {:?}", path));
    serde_json::from_str(&content).expect("Failed to parse keyboard JSON")
}

// Hydrates the Valkey instance with test assets from the temp directory.
pub async fn hydrate_test_valkey(state: &Arc<AppState>, root: &Path) {
    let system_root = root.join("user"); // Test uses user/ for convenience
    let walker = WalkDir::new(&system_root).follow_links(true);

    for entry in walker.into_iter().filter_map(|e| e.ok()) {
        if entry.file_type().is_file() {
            let path = entry.path();
            if let Ok(rel) = path.strip_prefix(&system_root) {
                let key_path = rel.to_string_lossy().replace('\\', "/");
                let valkey_key = format!("asset:blob:{}", key_path);

                if let Ok(content) = tokio::fs::read(path).await {
                    let packed = rmp_serde::to_vec(
                        &serde_json::from_slice::<serde_json::Value>(&content).unwrap(),
                    )
                    .unwrap();
                    let compressed =
                        zstd::stream::encode_all(std::io::Cursor::new(packed), 0).unwrap();

                    let store_key = if valkey_key.ends_with(".json") {
                        valkey_key.replace(".json", ".mpk.zst")
                    } else {
                        valkey_key
                    };

                    let _ = state.coordinator.set_bin(&store_key, &compressed).await;

                    let entry_id = if key_path.ends_with(".json") {
                        key_path.replace(".json", ".mpk.zst")
                    } else {
                        key_path.clone()
                    };

                    let hash = "test_hash".to_string(); // Mock hash
                    let entry = AssetManifestEntry {
                        id: entry_id,
                        hash,
                        size_bytes: compressed.len() as u64,
                        last_updated: 0,
                    };
                    let _ = state.coordinator.set_manifest_entry(&entry).await;
                }
            }
        }
    }
}

/// Sets up the test environment, including a Redis container and a temporary database.
pub async fn setup_server() -> (
    String,
    Arc<AppState>,
    tempfile::TempDir,
    ContainerAsync<Redis>,
) {
    init_tracing();

    let valkey_node = Redis::default()
        .start()
        .await
        .expect("Failed to start Valkey");
    let valkey_port = valkey_node
        .get_host_port_ipv4(6379)
        .await
        .expect("Failed to get port");
    let valkey_url = format!("redis://127.0.0.1:{}", valkey_port);
    std::env::set_var("KEYFORGE_VALKEY_URL", &valkey_url);

    let db_url = std::env::var("DATABASE_URL").unwrap_or_else(|_| {
        "postgres://keyforge:forge_password@localhost:5432/keyforge_hive".to_string()
    });

    let pool = init_db(&db_url).await;
    let _ = sqlx::query("TRUNCATE results CASCADE").execute(&pool).await;
    let _ = sqlx::query("TRUNCATE nodes CASCADE").execute(&pool).await;
    let _ = sqlx::query("TRUNCATE jobs CASCADE").execute(&pool).await;

    let temp_dir = tempfile::tempdir().unwrap();
    let data_path = temp_dir.path().to_path_buf();
    ensure_test_assets(&data_path);

    let mut config = keyforge_hive::config::AppConfig::mock();
    config.valkey_url = valkey_url;
    config.hive_secret = TEST_SECRET.to_string();

    let state = Arc::new(
        AppState::new(
            pool.clone(),
            data_path.clone(),
            "test-key".to_string(),
            config.clone(),
        )
        .await,
    );

    hydrate_test_valkey(&state, &data_path).await;

    let app = create_app(state.clone(), &config, data_path);
    let listener = TcpListener::bind("127.0.0.1:0").await.unwrap();
    let addr = listener.local_addr().unwrap();
    let port = addr.port();

    tokio::spawn(async move {
        axum::serve(
            listener,
            app.into_make_service_with_connect_info::<SocketAddr>(),
        )
        .await
        .unwrap();
    });

    let base_url = format!("http://127.0.0.1:{}", port);
    (base_url, state, temp_dir, valkey_node)
}

// apps/keyforge-hive/tests/concurrency.rs

//! # Concurrency Tests for KeyForge Hive
//!
//! Stress testing suite for the Hive server under high concurrent loads.

use futures::future::join_all;
use keyforge_model::config::{CorpusSource, ScoringWeights, SearchParams};
use keyforge_model::CostMatrixSource;
use keyforge_protocol::{
    JobConfig, JobRequest, JobResponse, NodeRequest, ResultSubmission, PROTOCOL_VERSION,
};
use reqwest::{header, Client};
use std::time::{Instant, SystemTime, UNIX_EPOCH};

mod common;
use common::*;

const NODE_COUNT: usize = 50;
const RESULTS_PER_NODE: usize = 100;

/// Performs a "thundering herd" stress test with multiple worker nodes
/// registering and submitting results simultaneously to ensure system stability.
#[tokio::test(flavor = "multi_thread", worker_threads = 8)]
async fn test_heterogeneous_thundering_herd() {
    let (base_url, _state, _temp_dir, _valkey) = setup_server().await;
    let data_root = _temp_dir.path();

    let mut headers = header::HeaderMap::new();
    let mut val = header::HeaderValue::from_static(TEST_SECRET);
    val.set_sensitive(true);
    headers.insert("X-Keyforge-Secret", val);

    let client = Client::builder()
        .default_headers(headers)
        .pool_max_idle_per_host(NODE_COUNT)
        .build()
        .unwrap();

    println!(" Starting Real-World Stress Test");
    println!("   Target: {}", base_url);

    let kb_corne = load_keyboard(data_root, "corne");
    let kb_szr = load_keyboard(data_root, "szr35");

    let weights_std = ScoringWeights::default();
    let mut weights_alt = ScoringWeights::default();
    weights_alt
        .weights
        .insert("penalty_scissor".to_string(), 500.0);

    let jobs_config = vec![
        (kb_corne.clone(), weights_std.clone(), "Corne-Std"),
        (kb_corne.clone(), weights_alt.clone(), "Corne-Alt"),
        (kb_szr.clone(), weights_std.clone(), "SZR-Std"),
        (kb_szr.clone(), weights_alt.clone(), "SZR-Alt"),
    ];

    let mut job_ids = Vec::new();

    for (kb, w, label) in jobs_config {
        let req = JobRequest {
            version: PROTOCOL_VERSION,
            config: JobConfig {
                definition: kb,
                weights: w,
                params: SearchParams::default(),
                pinned_keys: vec![],
                corpora: vec![CorpusSource {
                    id: "default".to_string(),
                    weight: 1.0,
                    hash: None,
                }],
                cost_matrix: CostMatrixSource::Predefined("cost_matrix.json".into()),
                biometrics: vec![],
                parent_job_id: None,
                baseline_score: None,
                parents: vec![],
            },
        };

        let resp = client
            .post(format!("{}/jobs", base_url))
            .json(&req)
            .send()
            .await
            .expect("Failed to send request");

        if !resp.status().is_success() {
            let status = resp.status();
            let text = resp.text().await.unwrap_or_default();
            panic!("❌ Job Registration Failed: {} - {}", status, text);
        }

        let body: JobResponse = resp.json().await.expect("Failed to parse JobResponse");
        println!("   📝 Registered {}: {}", label, &body.job_id[0..8]);
        job_ids.push(body.job_id);

        tokio::time::sleep(std::time::Duration::from_millis(100)).await;
    }

    let start_time = Instant::now();
    let mut handles = Vec::new();

    for i in 0..NODE_COUNT {
        let client_ref = client.clone();
        let url_ref = base_url.clone();
        let job_idx = i % 4;
        let target_job = job_ids[job_idx].clone();

        handles.push(tokio::spawn(async move {
            let node_id = format!("worker-{}-job-{}", i, job_idx);

            let reg_req = NodeRequest {
                version: PROTOCOL_VERSION,
                node_id: node_id.clone(),
                cpu_model: "RustTestCPU".into(),
                cores: 8,
                l2_cache_kb: Some(1024),
                ops_per_sec: 1_000_000.0,
                public_key: None,
            };

            // Retry loop for registration
            let mut attempts = 0;
            loop {
                let reg_resp = client_ref
                    .post(format!("{}/nodes/register", url_ref))
                    .json(&reg_req)
                    .send()
                    .await
                    .expect("Reg failed");

                if reg_resp.status().is_success() {
                    break;
                }

                attempts += 1;
                if attempts >= 5 {
                    return Err(format!(
                        "Node {} reg failed after 5 attempts: {}",
                        i,
                        reg_resp.status()
                    ));
                }
                tokio::time::sleep(std::time::Duration::from_millis(100 * attempts)).await;
            }

            for k in 0..RESULTS_PER_NODE {
                tokio::time::sleep(std::time::Duration::from_millis(10)).await;
                let timestamp = SystemTime::now()
                    .duration_since(UNIX_EPOCH)
                    .unwrap()
                    .as_secs();

                let res_req = ResultSubmission {
                    version: PROTOCOL_VERSION,
                    job_id: target_job.clone(),
                    layout: format!("Q W E R T Y U I O P A S D F G H J K L ; {} {}", i, k),
                    score: 500.0,
                    node_id: node_id.clone(),
                    timestamp,
                    nonce: fastrand::u64(..),
                    signature: "dummy".to_string(),
                };

                let res_resp = client_ref
                    .post(format!("{}/results", url_ref))
                    .json(&res_req)
                    .send()
                    .await
                    .expect("Submit failed");

                let status = res_resp.status();

                if status.is_server_error() {
                    let txt = res_resp.text().await.unwrap_or_default();
                    return Err(format!("Node {} crash: {} - {}", i, status, txt));
                }
            }
            Ok(())
        }));
    }

    let results = join_all(handles).await;
    let duration = start_time.elapsed();

    let mut failures = 0;
    for res in results {
        if let Ok(Err(e)) = res {
            println!("   ⚠️  Worker Error: {}", e);
            failures += 1;
        }
    }

    assert_eq!(failures, 0, "Clients encountered errors");

    let total_reqs = NODE_COUNT * RESULTS_PER_NODE;
    println!(
        "✅ Processed {} requests across 4 distinct jobs in {:.2}s",
        total_reqs,
        duration.as_secs_f32()
    );
}

