mod tests {
    use super::*;

    #[test]
    fn test_hardware_probe_runs() {
        let topology = HardwareProbe::probe();
        println!("Detected Topology: {:?}", topology);
        assert!(!topology.vendor.is_empty());
        // On some CI environments cpuid might be masked, but usually vendor is present.
    }
}

