/// An asset provider that loads data directly from the local filesystem.
///
/// It supports loading both system-level assets (stored in zstd-compressed `MessagePack`)
/// and user-level assets (stored as plain JSON).
#[derive(Clone, Debug)]
pub struct FsProvider {
    resolver: PathResolver,
}

impl FsProvider {
    /// Creates a new `FsProvider` with the specified root path.
    #[must_use]
    pub fn new(root: PathBuf) -> Self {
        Self {
            resolver: PathResolver::new(root),
        }
    }

    /// Returns the root directory of this provider.
    #[must_use]
    pub fn root(&self) -> &PathBuf {
        &self.resolver.root
    }

    async fn check_size(&self, path: &Path) -> LoaderResult<()> {
        let meta = tokio::fs::metadata(path).await?;
        if meta.len() > MAX_INPUT_FILE_SIZE {
            return Err(ForgeError::InvalidData(format!(
                "File {} exceeds size limit of {MAX_INPUT_FILE_SIZE} bytes",
                path.display()
            )));
        }
        Ok(())
    }

    async fn load_binary<T: serde::de::DeserializeOwned + Send + 'static>(
        &self,
        path: &Path,
    ) -> LoaderResult<T> {
        self.check_size(path).await?;
        let path = path.to_path_buf();
        tokio::task::spawn_blocking(move || {
            let file = File::open(&path)?;
            let decoder =
                zstd::Decoder::new(file).map_err(|e| ForgeError::Internal(e.to_string()))?;
            rmp_serde::from_read(decoder).map_err(|e| ForgeError::Internal(e.to_string()))
        })
        .await
        .map_err(|e| ForgeError::Internal(e.to_string()))?
    }

    async fn load_json<T: serde::de::DeserializeOwned + Send + 'static>(
        &self,
        path: &Path,
    ) -> LoaderResult<T> {
        self.check_size(path).await?;
        let path = path.to_path_buf();
        tokio::task::spawn_blocking(move || {
            let file = File::open(&path)?;
            let reader = BufReader::new(file);
            serde_json::from_reader(reader).map_err(ForgeError::Serde)
        })
        .await
        .map_err(|e| ForgeError::Internal(e.to_string()))?
    }

    /// Calculates a stable hash for a corpus by hashing its constituent parts.
    ///
    /// # Errors
    ///
    /// Returns `LoaderResult` if any constituent file cannot be read.
    pub async fn get_corpus_hash(&self, id: &str) -> LoaderResult<String> {
        // Task-infra-008: Security check
        let _ = self
            .resolver
            .safe_join(id)
            .map_err(ForgeError::InvalidData)?;

        let files = ["1grams", "2grams", "3grams", "words"];
        let is_system = self.resolver.root.join("system/corpora").join(id).exists();
        let base = if is_system {
            self.resolver.root.join("system/corpora").join(id)
        } else {
            self.resolver.root.join("user/corpora").join(id)
        };
        let ext = if is_system { "mpk.zst" } else { "json" };

        let mut hasher = sha2::Sha256::new();
        for f in files {
            let path = base.join(format!("{f}.{ext}"));
            if path.exists() {
                let content = tokio::fs::read(&path).await?;
                hasher.update(&content);
            }
        }
        Ok(hex::encode(hasher.finalize()))
    }
}

#[async_trait::async_trait]
impl AssetLoader for FsProvider {
    async fn load<T: Asset>(&self, id: &str) -> LoaderResult<Arc<T>> {
        let category = T::category();
        let cat_str = category.as_str();

        // Task-infra-008: Ensure ID is safe
        if id.contains("..") {
            self.resolver
                .safe_join(id)
                .map_err(ForgeError::InvalidData)?;
        }

        // 1. Try direct path (absolute or ./ relative)
        if let Some(p) = self.resolver.resolve_direct_path(id) {
            let mut asset: T = self.load_json(&p).await?;
            asset.post_load()?;
            return Ok(Arc::new(asset));
        }

        // Task-infra-020: Use Path for extension handling
        let path_id = Path::new(id);
        let stem = if path_id.extension().and_then(|s| s.to_str()) == Some("json") {
            path_id.file_stem().and_then(|s| s.to_str()).unwrap_or(id)
        } else {
            id
        };

        // 2. Try System Binary
        if let Some(p) = self.resolver.resolve_system_path(cat_str, stem) {
            let mut asset: T = self.load_binary(&p).await?;
            asset.post_load()?;
            return Ok(Arc::new(asset));
        }

        // 3. Try System JSON
        let system_json = self
            .resolver
            .root
            .join("system")
            .join(cat_str)
            .join(format!("{stem}.json"));
        if system_json.exists() {
            let mut asset: T = self.load_json(&system_json).await?;
            asset.post_load()?;
            return Ok(Arc::new(asset));
        }

        // 4. Try User JSON
        if let Some(p) = self.resolver.resolve_user_path(cat_str, stem) {
            let mut asset: T = self.load_json(&p).await?;
            asset.post_load()?;
            return Ok(Arc::new(asset));
        }

        Err(ForgeError::NotFound(id.to_string()))
    }

    async fn load_corpus(&self, sources: &[CorpusSource]) -> LoaderResult<Arc<Corpus>> {
        let mut corpus = Corpus::default();
        for src in sources {
            // Task-infra-008: Security check
            let _ = self
                .resolver
                .safe_join(&src.id)
                .map_err(ForgeError::InvalidData)?;

            let is_system = self
                .resolver
                .root
                .join("system/corpora")
                .join(&src.id)
                .exists();
            let base = if is_system {
                self.resolver.root.join("system/corpora").join(&src.id)
            } else {
                self.resolver.root.join("user/corpora").join(&src.id)
            };
            let ext = if is_system { "mpk.zst" } else { "json" };

            let mut segments = Vec::new();
            for stem in ["1grams", "2grams", "3grams", "words"] {
                let p = base.join(format!("{stem}.{ext}"));
                if p.exists() {
                    let part: Vec<serde_json::Value> = if is_system {
                        self.load_binary(&p).await?
                    } else {
                        self.load_json(&p).await?
                    };
                    segments.push((stem, part));
                }
            }

            crate::util::corpus::populate_corpus_from_segments(&mut corpus, src.weight, segments)?;
        }

        let is_std = sources.iter().any(|s| s.id.contains("_std"));
        inject_synthetic_data(&mut corpus, is_std);

        corpus.post_load()?;
        Ok(Arc::new(corpus))
    }
}

#[async_trait::async_trait]
impl AssetServerProvider for FsProvider {
    async fn get_manifest(&self) -> ServerManifest {
        let root = self.resolver.root.clone();
        tokio::task::spawn_blocking(move || {
            crate::net::sync::generate_manifest(&root.join("system")).unwrap_or(ServerManifest {
                files: std::collections::HashMap::default(),
            })
        })
        .await
        .unwrap_or(ServerManifest {
            files: std::collections::HashMap::default(),
        })
    }

    async fn get_file_content(&self, path: &str) -> Option<bytes::Bytes> {
        let Ok(safe_path) = self.resolver.safe_join(path) else {
            return None;
        };

        if safe_path.exists() {
            tokio::fs::read(safe_path)
                .await
                .ok()
                .map(bytes::Bytes::from)
        } else {
            None
        }
    }
}

// libs/keyforge-infra/src/asset/manager.rs

use crate::error::InfraResult;
use crate::net::client::HiveClient;
use crate::net::network::ensure_file;
use keyforge_model::constants::{
    ASSET_1GRAMS_FILENAME, ASSET_2GRAMS_FILENAME, ASSET_3GRAMS_FILENAME, ASSET_WORDS_FILENAME,
    DEFAULT_CORPUS_ID,
};
use keyforge_model::CostMatrixSource;
use keyforge_protocol::JobConfig;
use std::path::PathBuf;
use tracing::info;

#[derive(Debug)]
pub struct AssetManager {
    client: HiveClient,
    root: PathBuf,
}

impl AssetManager {
    #[must_use]
    pub fn new(client: HiveClient, root: PathBuf) -> Self {
        Self { client, root }
    }

    fn check_system_path(&self, category: &str, stem: &str) -> Option<PathBuf> {
        let sub = match category {
            "keyboards" => "keyboards/models",
            "weights" => "weights",
            "config" => "config",
            _ => category,
        };
        let p = self
            .root
            .join("system")
            .join(sub)
            .join(format!("{stem}.mpk.zst"));
        if p.exists() {
            Some(p)
        } else {
            None
        }
    }

    fn check_user_path(&self, category: &str, stem: &str) -> Option<PathBuf> {
        let p = self
            .root
            .join("user")
            .join(category)
            .join(format!("{stem}.json"));
        if p.exists() {
            Some(p)
        } else {
            None
        }
    }

    /// Ensures the specified keyboard file is present in the workspace.
    ///
    /// # Errors
    ///
    /// Returns `InfraError` if the file cannot be downloaded or verified.
    pub async fn ensure_keyboard(&self, name: &str) -> InfraResult<PathBuf> {
        let stem = name.strip_suffix(".json").unwrap_or(name);

        if let Some(p) = self.check_user_path("keyboards", stem) {
            return Ok(p);
        }
        if let Some(p) = self.check_system_path("keyboards", stem) {
            return Ok(p);
        }

        let local_path = self
            .root
            .join("user/keyboards")
            .join(format!("{stem}.json"));
        let remote_path = format!("data/keyboards/{stem}.json");
        let url = self.client.asset_url(&remote_path);

        ensure_file(&self.client, &url, &local_path, None).await?;
        Ok(local_path)
    }

    /// Ensures the specified cost matrix file is present in the workspace.
    ///
    /// # Errors
    ///
    /// Returns `InfraError` if the file cannot be downloaded or verified.
    pub async fn ensure_cost_matrix(&self, filename: &str) -> InfraResult<PathBuf> {
        let stem = filename.strip_suffix(".json").unwrap_or(filename);

        if let Some(p) = self.check_user_path("weights", stem) {
            return Ok(p);
        }
        if let Some(p) = self.check_system_path("weights", stem) {
            return Ok(p);
        }

        let local_path = self.root.join("user/weights").join(format!("{stem}.json"));
        let remote_path = format!("data/{stem}.json");
        let url = self.client.asset_url(&remote_path);

        ensure_file(&self.client, &url, &local_path, None).await?;
        Ok(local_path)
    }

    /// Ensures the specified corpus bundle is present in the workspace.
    ///
    /// # Errors
    ///
    /// Returns `InfraError` if any file in the bundle cannot be downloaded or verified.
    pub async fn ensure_corpus(
        &self,
        corpus_id: &str,
        expected_hash: Option<&str>,
    ) -> InfraResult<PathBuf> {
        let bundle_id = if corpus_id.is_empty() || corpus_id == "default" {
            DEFAULT_CORPUS_ID
        } else {
            corpus_id
        };

        // 1. Check System (Binary)
        let sys_dir = self.root.join("system/corpora").join(bundle_id);
        if sys_dir.join("1grams.mpk.zst").exists() {
            if let Some(hash) = expected_hash {
                let provider = crate::FsProvider::new(self.root.clone());
                if let Ok(h) = provider.get_corpus_hash(bundle_id).await {
                    if h == hash {
                        return Ok(sys_dir);
                    }
                    info!(
                        "System corpus '{}' hash mismatch. Falling back to User/Remote.",
                        bundle_id
                    );
                }
            } else {
                return Ok(sys_dir);
            }
        }

        // 2. Check User (JSON)
        let user_dir = self.root.join("user/corpora").join(bundle_id);
        let files = [
            ASSET_1GRAMS_FILENAME,
            ASSET_2GRAMS_FILENAME,
            ASSET_3GRAMS_FILENAME,
            ASSET_WORDS_FILENAME,
        ];

        let all_user_exist = files.iter().all(|f| user_dir.join(f).exists());

        if all_user_exist {
            if let Some(hash) = expected_hash {
                let provider = crate::FsProvider::new(self.root.clone());
                if let Ok(h) = provider.get_corpus_hash(bundle_id).await {
                    if h == hash {
                        return Ok(user_dir);
                    }
                }
            } else {
                return Ok(user_dir);
            }
        }

        // Download missing or mismatched files to USER directory
        for f in files {
            let local_path = user_dir.join(f);
            let remote_path = format!("data/corpora/{bundle_id}/{f}");
            let url = self.client.asset_url(&remote_path);

            ensure_file(&self.client, &url, &local_path, None).await?;
        }

        Ok(user_dir)
    }

    /// Synchronizes all assets required for a specific job.
    ///
    /// # Errors
    ///
    /// Returns `InfraError` if any asset fails to sync.
    ///
    /// # Panics
    ///
    /// Panics if the cost matrix path does not have a filename.
    pub async fn sync_job_assets(&self, config: &JobConfig) -> InfraResult<(String, String)> {
        info!("📦 Syncing assets for job...");
        let cost_path = match &config.cost_matrix {
            CostMatrixSource::Predefined(filename) => {
                let p = self.ensure_cost_matrix(filename).await?;
                p.file_name()
                    .ok_or_else(|| {
                        crate::error::InfraError::Io(std::io::Error::other(
                            "Invalid cost matrix path",
                        ))
                    })
                    .map(|s| s.to_string_lossy().to_string())?
            }
        };
        for source in &config.corpora {
            self.ensure_corpus(&source.id, source.hash.as_deref())
                .await?;
        }
        Ok((cost_path, "corpora".to_string()))
    }
}

