        geom.prime_slots = vec![KeyIndex(0)];
        geom.med_slots = vec![];
        geom.low_slots = vec![]; // Key 1 is missing
        assert!(geom.validate().is_err(), "Should fail on incomplete slots");

        // 6. Valid state
        geom.prime_slots = vec![KeyIndex(0)];
        geom.med_slots = vec![KeyIndex(1)];
        geom.low_slots = vec![];
        assert!(geom.validate().is_ok());
    }

