            [{"x":0},"A",{"x":1},"B"]
        ]"#;

        // Note: KeyboardDefinition::parse handles KLE detection
        let def = KeyboardDefinition::parse(json, Some("Test Board"));

        if let Ok(kb) = def {
            assert_eq!(kb.meta.name, "Test Board");
            assert_eq!(kb.geometry.keys.len(), 2);
        }
    }
}

