#[allow(clippy::cast_possible_wrap)]
pub fn score_layout(
    ctx: &EngineContext,
    layout: &ValidatedLayout<'_>,
    scratch: &mut PhysicsScratch,
) -> Result<i64, PhysicsError> {
    let layout_slice = layout.as_slice();
    let pm = PosMap::from_scratch(
        layout_slice,
        ctx.key_count,
        scratch.starts.as_mut_slice(),
        scratch.counts.as_mut_slice(),
        scratch.indices.as_mut_slice(),
        scratch.current_offsets.as_mut_slice(),
        &mut scratch.used_keys,
    );

    let m = score_monograms(ctx, &pm)?;
    let b = score_bigrams(ctx, &pm)?;
    let t = score_trigrams(ctx, &pm)?;

    let total = m.checked_add(b)
        .and_then(|sum| sum.checked_add(t))
        .ok_or_else(|| PhysicsError::ScoreOverflow {
            context: "Final kernel total score accumulation".to_string()
        })?;

    // Clean up scratch for next use
    scratch.clear_used();
    Ok(total.0)
}

#[allow(clippy::cast_possible_wrap)]
pub fn score_monograms(ctx: &EngineContext, pm: &PosMap<'_>) -> Result<Score, PhysicsError> {
    let mut total = Score::ZERO;
    for &code in pm.used_keys {
        let c_val = code as usize;
        let freq = ctx.char_freqs[c_val];
        if freq == 0 {
            continue;
        }
        let candidates = pm.get(c_val);
        if candidates.is_empty() {
            continue;
        }

        let mut min_cost = Score(i64::MAX);
        for &p in candidates {
            let cost = ctx.key_costs[p as usize];
            if cost < min_cost {
                min_cost = cost;
            }
        }

        if min_cost.0 != i64::MAX {
            let contrib = min_cost.checked_mul(freq as i64).ok_or_else(|| PhysicsError::ScoreOverflow {
                context: format!("Monogram freq scale for code {}", code)
            })?;
            total = total.checked_add(contrib).ok_or_else(|| PhysicsError::ScoreOverflow {
                context: format!("Monogram total accumulation at code {}", code)
            })?;
        }
    }
    Ok(total)
}

#[allow(clippy::cast_possible_wrap)]
pub fn score_bigrams(ctx: &EngineContext, pm: &PosMap<'_>) -> Result<Score, PhysicsError> {
    let mut total = Score::ZERO;
    for &code1 in pm.used_keys {
        let c1_val = code1 as usize;
        let candidates1 = pm.get(c1_val);
        let start = ctx.bigram_starts[c1_val];
        let end = ctx.bigram_starts[c1_val + 1];

        for k in start..end {
            let c2 = ctx.bigram_others[k];
            let candidates2 = pm.get(c2.0 as usize);
            if candidates2.is_empty() {
                continue;
            }

            let mut min_cost = Score(i64::MAX);
            for &p1 in candidates1 {
                for &p2 in candidates2 {
                    let idx = (p1 as usize) * ctx.key_count + (p2 as usize);
                    let mut cost = ctx.cost_matrix[idx];

                    if let Some(&mod_val) = ctx.sequence_modifiers.get(&(code1, c2.0)) {
                        cost = cost.checked_add(mod_val).ok_or_else(|| PhysicsError::ScoreOverflow {
                            context: format!("Bigram modifier for ({}, {})", code1, c2.0)
                        })?;
                    }

                    if cost < min_cost {
                        min_cost = cost;
                    }
                }
            }

            if min_cost.0 != i64::MAX {
                let freq = i64::from(ctx.bigram_freqs[k]);
                let contrib = min_cost.checked_mul(freq).ok_or_else(|| PhysicsError::ScoreOverflow {
                    context: format!("Bigram freq scale for ({}, {})", code1, c2.0)
                })?;
                total = total.checked_add(contrib).ok_or_else(|| PhysicsError::ScoreOverflow {
                    context: format!("Bigram total accumulation at ({}, {})", code1, c2.0)
                })?;
            }
        }
    }
    Ok(total)
}

#[allow(clippy::cast_possible_wrap)]
pub fn score_trigrams(ctx: &EngineContext, pm: &PosMap<'_>) -> Result<Score, PhysicsError> {
    let mut total = Score::ZERO;
    for &code1 in pm.used_keys {
        let c1_val = code1 as usize;
        let candidates1 = pm.get(c1_val);
        let start = ctx.trigram_starts[c1_val];
        let end = ctx.trigram_starts[c1_val + 1];

        for k in start..end {
            let c2 = ctx.trigram_others1[k];
            let c3 = ctx.trigram_others2[k];
            let candidates2 = pm.get(c2.0 as usize);
            let candidates3 = pm.get(c3.0 as usize);

            if candidates2.is_empty() || candidates3.is_empty() {
                continue;
            }

            let mut min_cost = Score(i64::MAX);
            for &p1 in candidates1 {
                for &p2 in candidates2 {
                    for &p3 in candidates3 {
                        let cost = calculate_flow_cost(ctx, p1 as usize, p2 as usize, p3 as usize);
                        if cost < min_cost {
                            min_cost = cost;
                        }
                    }
                }
            }

            if min_cost.0 != i64::MAX {
                let freq = i64::from(ctx.trigram_freqs[k]);
                let contrib = min_cost.checked_mul(freq).ok_or_else(|| PhysicsError::ScoreOverflow {
                    context: format!("Trigram freq scale for sequence starting with {}", code1)
                })?;
                total = total.checked_add(contrib).ok_or_else(|| PhysicsError::ScoreOverflow {
                    context: format!("Trigram total accumulation for sequence starting with {}", code1)
                })?;
            }
        }
    }
    Ok(total)
}

use crate::kernel::types::KeyCode;
use keyforge_model::constants::MAX_KEYBOARD_KEYS;
// use std::collections::HashMap; // Removed unused import

pub(crate) struct PosMap<'a> {
    pub(crate) starts: &'a [u16],
    pub(crate) counts: &'a [u8],
    pub(crate) indices: &'a [u16],
    pub(crate) used_keys: &'a [u16],
}

#[allow(clippy::cast_possible_truncation)]
impl<'a> PosMap<'a> {
    /// Creates a `PosMap` by manually populating the provided scratch buffers.
    /// This avoids large array initialization on every call.
    pub(crate) fn from_scratch(
        layout: &[KeyCode],
        key_count: usize,
        starts: &'a mut [u16],
        counts: &'a mut [u8],
        indices: &'a mut [u16],
        current_offsets: &mut [u8],
        used_keys_scratch: &'a mut Vec<u16>,
    ) -> Self {
        let limit = layout.len().min(key_count);

        // 1. Collect unique keys present in the layout
        used_keys_scratch.clear();
        for &code in layout.iter().take(limit) {
            used_keys_scratch.push(code.0);
        }
        used_keys_scratch.sort_unstable();
        used_keys_scratch.dedup();

        // 2. Clear counts for used keys
        for &code in used_keys_scratch.iter() {
            counts[code as usize] = 0;
        }

        // 3. Count occurrences
        for &code in layout.iter().take(limit) {
            counts[code.0 as usize] += 1;
        }

        // 4. Calculate starts (prefix sum)
        let mut offset = 0;
        for &code in used_keys_scratch.iter() {
            let c = code as usize;
            starts[c] = offset as u16;
            offset += counts[c] as usize;
        }

        // 5. Fill indices
        // Reset current_offsets
        for &code in used_keys_scratch.iter() {
            current_offsets[code as usize] = 0;
        }

        for (i, &code) in layout.iter().enumerate().take(limit) {
            let c = code.0 as usize;
            let base = starts[c] as usize;
            let off = current_offsets[c] as usize;
            indices[base + off] = i as u16;
            current_offsets[c] += 1;
        }

        Self {
            starts,
            counts,
            indices,
            used_keys: used_keys_scratch,
        }
    }

    /// Creates a `PosMap` from a flat position map slice.
    /// This is an optimized view into an existing position map.
    #[allow(dead_code)]
    pub(crate) fn from_slice(
        _pos_map: &'a [u16],
        _key_count: usize,
    ) -> Self {
        // Since we are using this for single-occurrence layouts (no duplicates),
        // we can simplify the PosMap to just use the pos_map directly if we change the structure.
        // For now, to keep parity with multi-occurrence logic, we have to keep the trait.
        // HOWEVER, the calculate_swap_delta in compute kernel takes &PosMap.

        // Wait, if there are no duplicates, starts[code] = offset, counts[code] = 1, indices[offset] = pos.
        // This is expensive to build here.

        // Let's check calculate_swap_delta signature.
        unimplemented!("PosMap::from_slice requires a scratch-less implementation of PosMap logic for performance parity.")
    }

    #[inline]
    pub(crate) fn get(&self, code: usize) -> &[u16] {
        if code >= 65536 {
            return &[];
        }
        let start = self.starts[code] as usize;
        let count = self.counts[code] as usize;
        if count == 0 {
            return &[];
        }
        &self.indices[start..start + count]
    }
}

/// Scratch space for physics operations to avoid re-allocating large arrays.
pub struct PhysicsScratch {
    pub(crate) starts: Box<[u16; 65536]>,
    pub(crate) counts: Box<[u8; 65536]>,
    pub(crate) indices: Box<[u16; MAX_KEYBOARD_KEYS]>,
    pub(crate) current_offsets: Box<[u8; 65536]>, // Helper buffer
    pub(crate) used_keys: Vec<u16>,
    pub(crate) char_usage: Box<[f32; 65536]>,
}

impl Default for PhysicsScratch {
    #[allow(clippy::unwrap_used)]
    fn default() -> Self {
        Self {
            starts: vec![0u16; 65536].into_boxed_slice().try_into().unwrap(),
            counts: vec![0u8; 65536].into_boxed_slice().try_into().unwrap(),
            indices: vec![0u16; MAX_KEYBOARD_KEYS]
                .into_boxed_slice()
                .try_into()
                .unwrap(),
            current_offsets: vec![0u8; 65536].into_boxed_slice().try_into().unwrap(),
            used_keys: Vec::with_capacity(MAX_KEYBOARD_KEYS),
            char_usage: vec![0.0f32; 65536].into_boxed_slice().try_into().unwrap(),
        }
    }
}

impl PhysicsScratch {
    /// Creates a new scratch instance.
    #[must_use]
    pub fn new() -> Self {
        Self::default()
    }

    pub(crate) fn clear_used(&mut self) {
        for &code in &self.used_keys {
            let c = code as usize;
            self.starts[c] = 0;
            self.counts[c] = 0;
            self.char_usage[c] = 0.0;
        }
    }
}

